import{_ as t,o as i,c as a,aa as o}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/en/diary/en_titulni_list1.jpg",n="/buildary-help-preview/media/en/diary/en_titulni_list2.jpg",s="/buildary-help-preview/media/en/diary/en_uvodni_list.jpg",d="/buildary-help-preview/media/en/diary/en_loga_grafika.jpg",l="/buildary-help-preview/media/en/diary/en_opravneneosoby.jpg",h="/buildary-help-preview/media/en/diary/en_doklady_stavby.jpg",_=JSON.parse('{"title":"Identification Details","description":"","frontmatter":{"title":"Identification Details","wiki":"en:diary:diaryidentification"},"headers":[],"relativePath":"en/diary/diaryidentification.md","filePath":"en/diary/diaryidentification.md","lastUpdated":1794388980000}'),c={name:"en/diary/diaryidentification.md"};function u(p,e,g,f,m,y){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="identification-details" tabindex="-1">Identification Details <a class="header-anchor" href="#identification-details" aria-label="Permalink to &quot;Identification Details&quot;">​</a></h1><p>The <strong>Identification Details</strong> represent <strong>Part A of the Construction Diary</strong>. This section consists of several sections. It includes the <strong>Diary Cover Sheet</strong>, containing information about the construction project and diary, as well as the <strong>Authorized Persons</strong> and their roles. Construction documents are divided into four sections.</p><p>The diary&#39;s Identification Details can be exported as a PDF at any time using the icon at the bottom of the Diary Cover Sheet.</p><figure class="shot" style="--w:600px;"><img src="'+r+'" alt="" width="600" loading="lazy"></figure><figure class="shot" style="--w:600px;"><img src="'+n+'" alt="" width="600" loading="lazy"></figure><h2 id="diary-cover-sheet" tabindex="-1">Diary Cover Sheet <a class="header-anchor" href="#diary-cover-sheet" aria-label="Permalink to &quot;Diary Cover Sheet&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+s+'" alt="" width="800" loading="lazy"></figure><p>All information shown on the Diary Cover Sheet is described in detail in the <strong>Creating and Setting Up a Diary</strong> section. This information can be edited at any time. Changes must always be saved.</p><h2 id="logos-and-graphics" tabindex="-1">Logos and Graphics <a class="header-anchor" href="#logos-and-graphics" aria-label="Permalink to &quot;Logos and Graphics&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+d+'" alt="" width="800" loading="lazy"></figure><p>In this window, you can select an <strong>image for the diary cover sheet</strong>. You can choose from three available options or upload your own image. Ideally, the recommended dimensions should be followed, but this is not required. The image will be automatically resized to fit.</p><p>You can also configure the <strong>Left Logo</strong> and <strong>Right Logo</strong> for the diary. For newly created diaries, the left logo is taken from the domain, while the right logo is populated with a default logo. An example of the resulting appearance is shown in the preview. We recommend using white logos with a transparent background, for example in PNG format.</p><h2 id="authorized-persons-and-their-roles-in-the-diary" tabindex="-1">Authorized Persons and Their Roles in the Diary <a class="header-anchor" href="#authorized-persons-and-their-roles-in-the-diary" aria-label="Permalink to &quot;Authorized Persons and Their Roles in the Diary&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+l+'" alt="" width="600" loading="lazy"></figure><p>The diary must contain a list of <strong>Authorized Persons</strong> who, under the law, either maintain the Construction Diary or have the right to enter records into it.</p><p>In Buildary, persons are selected for the diary from the <strong>Project Team Members</strong> list, which is maintained at the construction project level.</p><p><strong>Authorization to Perform Selected Activities in Construction</strong> The list of Authorized Persons in the diary allows you to attach the relevant authorization documents to each person. Persons for whom this is required by law should include an authorization stamp and handwritten signature on the cover sheets of the Construction Diary.</p><p>Our system offers essentially the same solution. In the Authorized Person editor, accessible via the pencil icon at the end of the relevant person&#39;s row, you can download the first page of the current diary using the <strong>Download Form</strong> option. After adding the authorization stamp and signature, you can upload the document as an attachment to the respective person. This also makes it possible to use a digital stamp and electronic signature.</p><p>If a physical stamp is used, we recommend performing an <strong>authorized conversion</strong> of the document into electronic form and then uploading the converted document as an attachment.</p><figure class="shot" style="--w:600px;"></figure><p>The authorization document is automatically included as an attachment in the diary&#39;s cover sheets PDF file, making it an integral part of the diary in electronic form.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A user&#39;s permissions are determined by their role in the Construction Diary. The same user may have different roles, and therefore different permissions, in different diaries.</p></div><p>The list of roles and their permissions is configured at the construction project level.</p><h2 id="construction-certificates-and-documents" tabindex="-1">Construction Certificates and Documents <a class="header-anchor" href="#construction-certificates-and-documents" aria-label="Permalink to &quot;Construction Certificates and Documents&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+h+'" alt="" width="600" loading="lazy"></figure><p>The four sections contain records of all certificates and documents related to the construction project. The purpose of the individual fields is clear from their names. Electronic documents can also be attached to records.</p><h2 id="diary-settings" tabindex="-1">Diary Settings <a class="header-anchor" href="#diary-settings" aria-label="Permalink to &quot;Diary Settings&quot;">​</a></h2><p>Diary settings are configured in the <strong><a href="/buildary-help-preview/en/diary/diarysetup#diary-settings">Creating and Setting Up a Diary</a></strong> section.</p>',28)])])}const v=t(c,[["render",u]]);export{_ as __pageData,v as default};
